// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.30;

import {Math} from "@openzeppelin4/contracts/utils/math/Math.sol";

import {RocketDAOProtocolSettingsMegapoolInterface} from "../../interface/dao/protocol/settings/RocketDAOProtocolSettingsMegapoolInterface.sol";
import {RocketDepositPoolInterface} from "../../interface/deposit/RocketDepositPoolInterface.sol";
import {RocketNodeDepositInterface} from "../../interface/node/RocketNodeDepositInterface.sol";
import {MinipoolStatus} from "../../types/MinipoolStatus.sol";
import {BeaconStateVerifierInterface, VerifiedValidator} from "../../interface/util/BeaconStateVerifierInterface.sol";
import {RocketBase} from "../RocketBase.sol";
import {RocketMegapoolStorageLayout} from "../megapool/RocketMegapoolStorageLayout.sol";
import {RocketMegapoolInterface} from "../../interface/megapool/RocketMegapoolInterface.sol";
import {RocketMinipoolInterface} from "../../interface/minipool/RocketMinipoolInterface.sol";
import {RocketMinipoolManagerInterface} from "../../interface/minipool/RocketMinipoolManagerInterface.sol";
import {RocketStorageInterface} from "../../interface/RocketStorageInterface.sol";
import {RocketNetworkExitInterface} from "../../interface/network/RocketNetworkExitInterface.sol";
import {RocketNetworkPenaltiesInterface} from "../../interface/network/RocketNetworkPenaltiesInterface.sol";
import {RocketDAOProtocolSettingsNetworkInterface} from "../../interface/dao/protocol/settings/RocketDAOProtocolSettingsNetworkInterface.sol";

/// @notice Handles cooperative and forced exits of Minipool and Megapool validators
contract RocketNetworkExit is RocketBase, RocketNetworkExitInterface {

    // Events

    event MegapoolExitRequested(address indexed megapoolAddress, uint256 indexed _validatorId, bytes pubkey);
    event MinipoolExitRequested(address indexed minipoolAddress, bytes pubkey);
    event MinipoolPenalised(address indexed minipoolAddress, uint256 _amount);
    event MegapoolVoluntaryExitRecorded(address indexed megapoolAddress, uint256 indexed validatorId, uint256 expectedUserCapital);
    event MegapoolExitReconciled(address indexed megapoolAddress, uint256 indexed validatorId, ExitType exitType, uint256 expectedUserCapital);
    event MinipoolExitReconciled(address indexed minipoolAddress, uint256 expectedUserCapital);

    // Constants

    uint256 constant internal farFutureEpoch = 2 ** 64 - 1;
    uint256 constant internal slotRecencyThreshold = 1 hours;
    uint256 constant internal validatorDeposit = 32 ether;

    // Immutables

    address payable immutable internal withdrawalRequestPredeployAddress;

    // Modifiers

    modifier onlyMinipoolExitRequester() {
        require(
            msg.sender == getContractAddress("rocketNetworkRedemptions") ||
            msg.sender == getContractAddress("rocketNetworkParticipation"),
            "Invalid minipool exit requester"
        );
        _;
    }

    modifier onlyMegapoolExitRequester() {
        require(
            msg.sender == getContractAddress("rocketNetworkRedemptions") ||
            msg.sender == getContractAddress("rocketNetworkParticipation"),
            "Invalid megapool exit requester"
        );
        _;
    }

    modifier onlyLatestMegapoolManager() {
        require(msg.sender == getContractAddress("rocketMegapoolManager"), "Invalid megapool manager");
        _;
    }

    // Construct

    constructor(RocketStorageInterface _rocketStorageAddress, address payable _withdrawalRequestPredeployAddress) RocketBase(_rocketStorageAddress) {
        version = 1;
        withdrawalRequestPredeployAddress = _withdrawalRequestPredeployAddress;
    }

    /// @notice Returns the amount of ETH expected to exit
    function getRequestedEth() override public view returns (uint256) {
        return getUint(keccak256(bytes("exit.requested.eth")));
    }

    /// @notice Returns the amount of ETH expected from voluntarily exiting Megapool validators
    function getVoluntaryEth() override public view returns (uint256) {
        return getUint(keccak256(bytes("exit.voluntary.eth")));
    }

    /// @notice Returns the exact current EIP-7002 exit fee
    function getExitFee() override public view returns (uint256) {
        (bool result, bytes memory feeRaw) = withdrawalRequestPredeployAddress.staticcall("");
        require(result, "Withdrawal fee query failed");
        require(feeRaw.length == 32, "Invalid withdrawal fee response");
        return abi.decode(feeRaw, (uint256));
    }

    /// @notice Returns the start of the cooperative exit phase for a given Minipool
    /// @param _minipoolAddress The address of the Minipool
    function getMinipoolCooperativeExitStart(address _minipoolAddress) override public view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("exit.request.minipool.time", _minipoolAddress)));
    }

    /// @notice Returns the start of the cooperative exit phase for a given Megapool validator
    /// @param _megapoolAddress The address of the Megapool owning the validator
    /// @param _validatorId The internal ID of the validator within the Megapool
    function getMegapoolCooperativeExitStart(address _megapoolAddress, uint32 _validatorId) override public view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("exit.request.megapool.time", _megapoolAddress, _validatorId)));
    }

    /// @notice Returns the timestamp of the last exit request for a Minipool (or 0 if never requested)
    /// @param _minipoolAddress The address of the Minipool
    function getMinipoolLastExit(address _minipoolAddress) override public view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("exit.last.minipool.time", _minipoolAddress)));
    }

    /// @notice Returns the number of times a Minipool has been requested to exit
    /// @param _minipoolAddress The address of the Minipool
    function getMinipoolExitRequestCount(address _minipoolAddress) override public view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("exit.request.minipool.count", _minipoolAddress)));
    }

    /// @notice Returns the expected user capital snapshotted for a requested Minipool
    function getMinipoolExpectedUserCapital(address _minipoolAddress) override public view returns (uint256) {
        return getUint(minipoolExpectedUserCapitalKey(_minipoolAddress));
    }

    /// @notice Returns how a Megapool validator is currently accounted for
    function getMegapoolExitType(address _megapoolAddress, uint32 _validatorId) override public view returns (ExitType) {
        return ExitType(getUint(megapoolExitTypeKey(_megapoolAddress, _validatorId)));
    }

    /// @notice Returns the expected user capital snapshotted for a Megapool validator
    function getMegapoolExpectedUserCapital(address _megapoolAddress, uint32 _validatorId) override public view returns (uint256) {
        return getUint(megapoolExpectedUserCapitalKey(_megapoolAddress, _validatorId));
    }

    /// @notice Returns the number of requested and voluntary exits outstanding for a Megapool
    function getMegapoolOutstandingExitCount(address _megapoolAddress) override public view returns (uint256) {
        return getUint(megapoolOutstandingExitCountKey(_megapoolAddress));
    }

    /// @notice Requests a specific Minipool to exit cooperatively
    /// @param _minipoolAddress The address of the Minipool
    function requestMinipoolExit(address _minipoolAddress) override external onlyMinipoolExitRequester onlyRegisteredMinipool(_minipoolAddress) {
        // Check this Minipool is clear to exit
        require(getMinipoolCooperativeExitStart(_minipoolAddress) == 0, "Minipool already requested to exit");
        uint256 requestCount = getMinipoolExitRequestCount(_minipoolAddress);
        if (requestCount > 0) {
            uint256 delay = _applyBackoff(_getDidNotExitBase(), requestCount - 1);
            require(block.timestamp >= getMinipoolLastExit(_minipoolAddress) + delay, "Not enough time has passed");
        }
        // Get contracts
        RocketMinipoolInterface minipool = RocketMinipoolInterface(_minipoolAddress);
        RocketMinipoolManagerInterface minipoolManager = RocketMinipoolManagerInterface(getContractAddress("rocketMinipoolManager"));
        require(minipool.getStatus() == MinipoolStatus.Staking, "Minipool is not staking");
        require(!minipool.getFinalised(), "Minipool is finalised");
        require(!minipool.getUserDistributed(), "User capital already distributed");
        // Start the cooperative exit timer and set last exit attempt
        _startMinipoolCooperativeExit(_minipoolAddress);
        _setMinipoolLastExit(_minipoolAddress);
        _setMinipoolExitRequestCount(_minipoolAddress, requestCount + 1);
        // Increment requested ETH value
        uint256 expectedUserCapital = minipool.getUserDepositBalance();
        _increaseRequestedEth(expectedUserCapital, minipoolExpectedUserCapitalKey(_minipoolAddress));
        // Emit events
        bytes memory pubkey = minipoolManager.getMinipoolPubkey(_minipoolAddress);
        emit MinipoolExitRequested(_minipoolAddress, pubkey);
    }

    /// @notice Forces a Minipool to exit if they have failed to exit cooperatively and their delegate supports an EL triggered exits
    /// @param _minipoolAddress The address of the Minipool
    function forceMinipoolExit(address _minipoolAddress) override public payable onlyRegisteredMinipool(_minipoolAddress) {
        // Check that the cooperative exit time has been satisfied
        _validateMinipoolCooperativeExit(_minipoolAddress, block.timestamp);
        // Check if the Minipool supports force exits (otherwise caller should use `penaliseMinipool` instead)
        RocketMinipoolInterface minipool = RocketMinipoolInterface(_minipoolAddress);
        uint8 version = minipool.version();
        require(version >= 4, "Delegate does not support force exit");
        bytes32 submittedKey = minipoolForceExitSubmittedKey(_minipoolAddress);
        require(!getBool(submittedKey), "Force exit already submitted");
        // Query and forward the exact fee so the predeploy does not retain an overpayment
        uint256 fee = getExitFee();
        require(msg.value >= fee, "Insufficient exit fee");
        // Set replay protection before external calls; all state is rolled back if submission or refund fails
        setBool(submittedKey, true);
        minipool.forceExit{value: fee}();
        _refundExcessExitFee(fee);
    }

    /// @notice Penalises a Minipool if they have failed to cooperatively exit (or falls back to force exit if it supports EL triggered exits)
    /// @param _minipoolAddress The address of the Minipool
    /// @param _slotTimestamp Timestamp of the slot for which the validator proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function penaliseMinipool(address _minipoolAddress, uint64 _slotTimestamp, uint256 _proofVersion, bytes calldata _proofData) override external payable onlyRegisteredMinipool(_minipoolAddress) {
        // Require a recent proof
        require(_slotTimestamp + slotRecencyThreshold >= block.timestamp, "Slot proof too old");
        // Check if the Minipool supports force exits
        RocketMinipoolInterface minipool = RocketMinipoolInterface(_minipoolAddress);
        uint8 version = minipool.version();
        if (version >= 4) {
            // Instead of reverting here, we can fallback to a force exit
            // This prevents the NO from frontrunning a penalise call with a delegate fallback to make it revert
            forceMinipoolExit(_minipoolAddress);
            return;
        }
        require(msg.value == 0, "Unexpected exit fee");
        // Check that the cooperative exit time has been satisfied
        _validateMinipoolCooperativeExit(_minipoolAddress, _slotTimestamp);
        // Get the validator pubkey
        RocketMinipoolManagerInterface minipoolManager = RocketMinipoolManagerInterface(getContractAddress("rocketMinipoolManager"));
        bytes memory pubkey = minipoolManager.getMinipoolPubkey(_minipoolAddress);
        // Verify the proofs
        BeaconStateVerifierInterface beaconStateVerifier = BeaconStateVerifierInterface(getContractAddress("beaconStateVerifier"));
        VerifiedValidator memory verified = beaconStateVerifier.verifyValidator(_slotTimestamp, _proofVersion, _proofData);
        // Validate the proof
        require(verified.validator.exitEpoch == farFutureEpoch);
        require(keccak256(verified.validator.pubkey) == keccak256(pubkey), "Incorrect validator");
        // Apply penalty to the Minipool
        _applyMinipoolPenalty(_minipoolAddress);
        // Decrease requested ETH
        _decreaseRequestedEth(minipoolExpectedUserCapitalKey(_minipoolAddress));
        // Clear the cooperative exit start timer so a future attempt can be made
        _clearMinipoolCooperativeExit(_minipoolAddress);
    }

    /// @dev Requests that a Megapool validator be exited
    /// @param _megapoolAddress Address of the Megapool which owns the validator
    /// @param _validatorId Internal ID of the validator for the given Megapool
    function requestMegapoolExit(address _megapoolAddress, uint32 _validatorId) override external onlyMegapoolExitRequester onlyRegisteredMegapool(_megapoolAddress) {
        RocketMegapoolInterface megapool = RocketMegapoolInterface(_megapoolAddress);
        (RocketMegapoolStorageLayout.ValidatorInfo memory validator, bytes memory pubkey) = megapool.getValidatorInfoAndPubkey(_validatorId);
        require(validator.staked, "Validator is not staking");
        require(!validator.dissolved, "Validator is dissolved");
        require(!validator.exiting, "Validator is exiting");
        require(!validator.exited, "Validator has exited");
        require(getMegapoolExitType(_megapoolAddress, _validatorId) == ExitType.None, "Validator exit already tracked");
        // Start the cooperative exit timer
        _startMegapoolCooperativeExit(_megapoolAddress, _validatorId);
        // Snapshot and account for the expected user capital
        uint256 expectedUserCapital = _calculateMegapoolExpectedUserCapital(megapool);
        _recordMegapoolExit(_megapoolAddress, _validatorId, ExitType.Requested, expectedUserCapital);
        // Emit event
        emit MegapoolExitRequested(_megapoolAddress, _validatorId, pubkey);
    }

    /// @dev Triggers an EL exit for a Megapool validator if cooperative exit was not performed
    /// @param _megapoolAddress Address of the Megapool owning the validator
    /// @param _validatorId Internal ID of the validator within the Megapool
    function forceMegapoolExit(address _megapoolAddress, uint32 _validatorId) override external payable onlyRegisteredMegapool(_megapoolAddress) {
        // Check that the cooperative exit time has been satisfied
        _validateMegapoolCooperativeExit(_megapoolAddress, _validatorId);
        // Force exit the validator using the common caller-funded execution path
        RocketMegapoolInterface megapool = RocketMegapoolInterface(_megapoolAddress);
        uint32[] memory validatorIds = new uint32[](1);
        validatorIds[0] = _validatorId;
        _forceMegapoolValidators(megapool, validatorIds);
    }

    /// @notice Permissionlessly resubmits an EL exit for a validator already marked as exiting
    /// @dev Success means the request was queued, not that consensus accepted the exit. The caller funds the current fee.
    /// @param _megapoolAddress Address of the Megapool owning the validator
    /// @param _validatorId Internal ID of the validator within the Megapool
    function retryMegapoolExit(address _megapoolAddress, uint32 _validatorId) override external payable onlyRegisteredMegapool(_megapoolAddress) {
        uint256 fee = getExitFee();
        require(msg.value >= fee, "Insufficient exit fee");
        RocketMegapoolInterface(_megapoolAddress).retryExit{value: fee}(_validatorId);
        _refundExcessExitFee(fee);
    }

    /// @notice Exits Megapool validators at the request of the node or its withdrawal address, or permissionlessly when the deficit permits
    /// @dev Other callers require the projected deficit before the last requested exit to be at least the RPIP-44 exit deficit
    /// @param _megapoolAddress Address of the Megapool owning the validators
    /// @param _validatorIds Internal IDs of the validators to exit
    function exitMegapoolValidators(address _megapoolAddress, uint32[] calldata _validatorIds) override external payable onlyRegisteredMegapool(_megapoolAddress) {
        uint256 numValidatorsToExit = _validatorIds.length;
        require(numValidatorsToExit > 0, "No validators supplied");
        // Get contracts
        RocketMegapoolInterface megapool = RocketMegapoolInterface(_megapoolAddress);
        // Query validator counts
        uint256 totalExiting = numValidatorsToExit + megapool.getExitingValidatorCount();
        uint256 activeValidatorCount = megapool.getActiveValidatorCount();
        // Sanity check validator exit count
        require(totalExiting <= activeValidatorCount, "Too many validators to exit");
        // Skip deficit accounting for owners
        address nodeAddress = megapool.getNodeAddress();
        if (msg.sender != nodeAddress && msg.sender != rocketStorage.getNodeWithdrawalAddress(nodeAddress)) {
            RocketDepositPoolInterface rocketDepositPool = RocketDepositPoolInterface(getContractAddress("rocketDepositPool"));
            RocketDAOProtocolSettingsMegapoolInterface rocketDAOProtocolSettingsMegapool = RocketDAOProtocolSettingsMegapoolInterface(getContractAddress("rocketDAOProtocolSettingsMegapool"));
            RocketNodeDepositInterface rocketNodeDeposit = RocketNodeDepositInterface(getContractAddress("rocketNodeDeposit"));
            // Query credit and rewards
            uint256 credit = rocketDepositPool.getNodeCreditBalance(nodeAddress);
            (uint256 rewards,,,) = megapool.calculatePendingRewards();
            // Account for existing exits and every proposed exit except the last
            // The last exit is allowed to bring the deficit below the threshold
            // Include queued bond because the active validator count includes queued validators
            // Clamp release to zero when underbonded and cap it by exiting principal and available node bond
            uint256 bondReleasedBeforeLast = _calculateReleasedNodeBond(
                megapool.getNodeBond() + megapool.getNodeQueuedBond(),
                megapool.getNodeBond(),
                rocketNodeDeposit.getBondRequirement(activeValidatorCount - (totalExiting - 1)),
                totalExiting - 1
            );
            uint256 projectedExcess = credit + rewards + bondReleasedBeforeLast;
            // Pending rewards exclude already-distributed funds available for refund
            projectedExcess += megapool.getRefundValue();
            // Include deposited node ETH available for validator deposits (RPIP-44 received funds)
            projectedExcess += rocketNodeDeposit.getNodeEthBalance(nodeAddress);
            require(megapool.getDebt() >= rocketDAOProtocolSettingsMegapool.getExitDeficit() + projectedExcess, "Deficit too low");
        }
        // Exit validators using the common caller-funded execution path
        _forceMegapoolValidators(megapool, _validatorIds);
    }

    /// @notice Records a successfully notified Megapool exit as voluntary unless it was already requested
    function notifyMegapoolExit(address _megapoolAddress, uint32 _validatorId) override external onlyLatestMegapoolManager onlyRegisteredMegapool(_megapoolAddress) {
        ExitType exitType = getMegapoolExitType(_megapoolAddress, _validatorId);
        if (exitType == ExitType.Requested) {
            return;
        }
        require(exitType == ExitType.None, "Validator exit already tracked");
        RocketMegapoolInterface megapool = RocketMegapoolInterface(_megapoolAddress);
        RocketMegapoolStorageLayout.ValidatorInfo memory validator = megapool.getValidatorInfo(_validatorId);
        require(validator.exiting && !validator.exited, "Validator is not exiting");
        // Dissolved validators have already had their capital reconciled and are not voluntary exits
        if (validator.dissolved) {
            return;
        }
        uint256 expectedUserCapital = _calculateMegapoolExpectedUserCapital(megapool);
        _recordMegapoolExit(_megapoolAddress, _validatorId, ExitType.Voluntary, expectedUserCapital);
        emit MegapoolVoluntaryExitRecorded(_megapoolAddress, _validatorId, expectedUserCapital);
    }

    /// @notice Reconciles a Megapool validator after its final balance has been processed
    function notifyMegapoolFinalBalance(address _megapoolAddress, uint32 _validatorId) override external onlyLatestMegapoolManager onlyRegisteredMegapool(_megapoolAddress) {
        ExitType exitType = getMegapoolExitType(_megapoolAddress, _validatorId);
        // Validators already exiting at upgrade time do not have an accounting record
        if (exitType == ExitType.None) {
            return;
        }
        uint256 expectedUserCapital = getMegapoolExpectedUserCapital(_megapoolAddress, _validatorId);
        if (exitType == ExitType.Requested) {
            subUint(keccak256(bytes("exit.requested.eth")), expectedUserCapital);
            _clearMegapoolCooperativeExit(_megapoolAddress, _validatorId);
        } else {
            subUint(keccak256(bytes("exit.voluntary.eth")), expectedUserCapital);
        }
        deleteUint(megapoolExpectedUserCapitalKey(_megapoolAddress, _validatorId));
        deleteUint(megapoolExitTypeKey(_megapoolAddress, _validatorId));
        subUint(megapoolOutstandingExitCountKey(_megapoolAddress), 1);
        emit MegapoolExitReconciled(_megapoolAddress, _validatorId, exitType, expectedUserCapital);
    }

    /// @notice Reconciles a requested Minipool once user capital has been distributed
    function settleMinipoolExit(address _minipoolAddress) override external onlyRegisteredMinipool(_minipoolAddress) {
        require(getMinipoolCooperativeExitStart(_minipoolAddress) != 0, "Minipool exit is not requested");
        RocketMinipoolInterface minipool = RocketMinipoolInterface(_minipoolAddress);
        require(minipool.getFinalised() || minipool.getUserDistributed(), "Minipool has not distributed");
        uint256 expectedUserCapital = getMinipoolExpectedUserCapital(_minipoolAddress);
        _decreaseRequestedEth(minipoolExpectedUserCapitalKey(_minipoolAddress));
        _clearMinipoolCooperativeExit(_minipoolAddress);
        emit MinipoolExitReconciled(_minipoolAddress, expectedUserCapital);
    }

    // Internals

    function _increaseRequestedEth(uint256 _amount, bytes32 _key) internal {
        addUint(keccak256(bytes("exit.requested.eth")), _amount);
        setUint(_key, _amount);
    }

    function _decreaseRequestedEth(bytes32 _key) internal {
        uint256 amount = getUint(_key);
        subUint(keccak256(bytes("exit.requested.eth")), amount);
        deleteUint(_key);
    }

    function _startMinipoolCooperativeExit(address _minipoolAddress) internal {
        setUint(keccak256(abi.encodePacked("exit.request.minipool.time", _minipoolAddress)), block.timestamp);
    }

    function _setMinipoolLastExit(address _minipoolAddress) internal {
        setUint(keccak256(abi.encodePacked("exit.last.minipool.time", _minipoolAddress)), block.timestamp);
    }

    function _setMinipoolExitRequestCount(address _minipoolAddress, uint256 _count) internal {
        setUint(keccak256(abi.encodePacked("exit.request.minipool.count", _minipoolAddress)), _count);
    }

    function _clearMinipoolCooperativeExit(address _minipoolAddress) internal {
        deleteUint(keccak256(abi.encodePacked("exit.request.minipool.time", _minipoolAddress)));
        deleteBool(minipoolForceExitSubmittedKey(_minipoolAddress));
    }

    function _startMegapoolCooperativeExit(address _megapoolAddress, uint32 _validatorId) internal {
        setUint(keccak256(abi.encodePacked("exit.request.megapool.time", _megapoolAddress, _validatorId)), block.timestamp);
    }

    function _clearMegapoolCooperativeExit(address _megapoolAddress, uint32 _validatorId) internal {
        deleteUint(keccak256(abi.encodePacked("exit.request.megapool.time", _megapoolAddress, _validatorId)));
    }

    function _recordMegapoolExit(address _megapoolAddress, uint32 _validatorId, ExitType _exitType, uint256 _expectedUserCapital) internal {
        setUint(megapoolExitTypeKey(_megapoolAddress, _validatorId), uint256(_exitType));
        setUint(megapoolExpectedUserCapitalKey(_megapoolAddress, _validatorId), _expectedUserCapital);
        addUint(megapoolOutstandingExitCountKey(_megapoolAddress), 1);
        if (_exitType == ExitType.Requested) {
            addUint(keccak256(bytes("exit.requested.eth")), _expectedUserCapital);
        } else {
            addUint(keccak256(bytes("exit.voluntary.eth")), _expectedUserCapital);
        }
    }

    /// @dev Returns the expected user capital returned from exiting a Megapool validator
    function _calculateMegapoolExpectedUserCapital(RocketMegapoolInterface _megapool) internal view returns (uint256) {
        uint256 activeValidatorCount = _megapool.getActiveValidatorCount();
        uint256 outstandingExitCount = getMegapoolOutstandingExitCount(address(_megapool));
        require(outstandingExitCount < activeValidatorCount, "Too many outstanding exits");
        RocketNodeDepositInterface rocketNodeDeposit = RocketNodeDepositInterface(getContractAddress("rocketNodeDeposit"));
        uint256 releasedBefore = 0;
        uint256 nodeBond = _megapool.getNodeBond();
        uint256 effectiveBond = nodeBond + _megapool.getNodeQueuedBond();
        if (outstandingExitCount > 0) {
            uint256 previousRequirement = rocketNodeDeposit.getBondRequirement(activeValidatorCount - outstandingExitCount);
            releasedBefore = _calculateReleasedNodeBond(effectiveBond, nodeBond, previousRequirement, outstandingExitCount);
        }
        uint256 newOutstandingExitCount = outstandingExitCount + 1;
        uint256 newRequirement = rocketNodeDeposit.getBondRequirement(activeValidatorCount - newOutstandingExitCount);
        uint256 releasedAfter = _calculateReleasedNodeBond(effectiveBond, nodeBond, newRequirement, newOutstandingExitCount);
        uint256 marginalBond = releasedAfter - releasedBefore;
        return validatorDeposit - marginalBond;
    }

    function _calculateReleasedNodeBond(uint256 _effectiveBond, uint256 _nodeBond, uint256 _bondRequirement, uint256 _exitCount) internal pure returns (uint256) {
        if (_effectiveBond <= _bondRequirement) {
            return 0;
        }
        uint256 released = _effectiveBond - _bondRequirement;
        uint256 validatorLimit = validatorDeposit * _exitCount;
        if (released > validatorLimit) {
            released = validatorLimit;
        }
        if (released > _nodeBond) {
            released = _nodeBond;
        }
        return released;
    }

    /// @dev Returns the "cooperative exit" deadline a NO has to exit on their own before being forced
    function _getCooperativeExitPhase() internal view returns (uint256) {
        return _getNetworkSettings().getCooperativeExitPhase();
    }

    /// @dev Returns the base penalty in ETH for not exiting when requested
    function _getDidNotExitPenaltyBase() internal view returns (uint256) {
        return _getNetworkSettings().getDidNotExitPenaltyBase();
    }

    /// @dev Returns the base delay before a Minipool can be requested to exit again
    function _getDidNotExitBase() internal view returns (uint256) {
        return _getNetworkSettings().getDidNotExitBase();
    }

    /// @dev Returns the backoff multiplier applied after each failed exit
    function _getDidNotExitBackoff() internal view returns (uint256) {
        return _getNetworkSettings().getDidNotExitBackoff();
    }

    function _getNetworkSettings() internal view returns (RocketDAOProtocolSettingsNetworkInterface) {
        return RocketDAOProtocolSettingsNetworkInterface(getContractAddress("rocketDAOProtocolSettingsNetwork"));
    }

    /// @dev Executes one EIP-7002 request per validator and refunds any unused caller-supplied fee
    function _forceMegapoolValidators(RocketMegapoolInterface _megapool, uint32[] memory _validatorIds) internal {
        uint256 fee = getExitFee();
        uint256 requiredFee = fee * _validatorIds.length;
        require(msg.value >= requiredFee, "Insufficient exit fee");

        for (uint256 i = 0; i < _validatorIds.length; ++i) {
            _megapool.forceExit{value: fee}(_validatorIds[i]);
        }

        _refundExcessExitFee(requiredFee);
    }

    /// @dev Refunds caller-supplied ETH that was not used for EIP-7002 requests
    function _refundExcessExitFee(uint256 _usedFee) internal {
        uint256 refund = msg.value - _usedFee;
        if (refund > 0) {
            (bool success,) = payable(msg.sender).call{value: refund}("");
            require(success, "Exit fee refund failed");
        }
    }

    /// @dev Reverts if Minipool has not been requested to exit or the cooperative exit phase has not been waited
    function _validateMinipoolCooperativeExit(address _minipoolAddress, uint256 _timestamp) internal {
        uint256 requestTime = getMinipoolCooperativeExitStart(_minipoolAddress);
        require(requestTime != 0, "Force exit has not been requested");
        require(requestTime <= _timestamp - _getCooperativeExitPhase(), "Not enough time has passed");
    }

    /// @dev Reverts if Megapool validator has not been requested to exit or the cooperative exit phase has not been waited
    function _validateMegapoolCooperativeExit(address _megapoolAddress, uint32 _validatorId) internal {
        uint256 requestTime = getMegapoolCooperativeExitStart(_megapoolAddress, _validatorId);
        require(requestTime != 0, "Force exit has not been requested");
        require(requestTime <= block.timestamp - _getCooperativeExitPhase(), "Not enough time has passed");
    }

    /// @dev Increases the penalty rate on a Minipool by the "did not exit penalty"
    /// @param _minipoolAddress Address of the Minipool to penalise
    function _applyMinipoolPenalty(address _minipoolAddress) internal {
        // Exit policy determines the nominal amount; NetworkPenalties owns conversion and combined rate accounting
        uint256 requestCount = getMinipoolExitRequestCount(_minipoolAddress);
        require(requestCount > 0, "Minipool has not been requested to exit");
        uint256 penaltyAmount = _applyBackoff(_getDidNotExitPenaltyBase(), requestCount - 1);
        RocketNetworkPenaltiesInterface(getContractAddress("rocketNetworkPenalties")).applyExitPenalty(_minipoolAddress, penaltyAmount);
        // Emit event
        emit MinipoolPenalised(_minipoolAddress, penaltyAmount);
    }

    /// @dev Applies the configured fixed-point backoff to a base value
    function _applyBackoff(uint256 _base, uint256 _exponent) internal view returns (uint256) {
        uint256 result = calcBase;
        uint256 multiplier = _getDidNotExitBackoff();
        while (_exponent > 0) {
            if ((_exponent & 1) == 1) {
                result = Math.mulDiv(result, multiplier, calcBase);
            }
            _exponent >>= 1;
            if (_exponent > 0) {
                multiplier = Math.mulDiv(multiplier, multiplier, calcBase);
            }
        }
        return Math.mulDiv(_base, result, calcBase);
    }

    // Key builders

    function minipoolExpectedUserCapitalKey(address _minipoolAddress) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("exit.requested.eth.minipool", _minipoolAddress));
    }

    function minipoolForceExitSubmittedKey(address _minipoolAddress) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("exit.request.minipool.force.submitted", _minipoolAddress));
    }

    function megapoolExitTypeKey(address _megapoolAddress, uint32 _validatorId) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("exit.megapool.type", _megapoolAddress, _validatorId));
    }

    function megapoolExpectedUserCapitalKey(address _megapoolAddress, uint32 _validatorId) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("exit.megapool.expected.user.capital", _megapoolAddress, _validatorId));
    }

    function megapoolOutstandingExitCountKey(address _megapoolAddress) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("exit.megapool.outstanding.count", _megapoolAddress));
    }
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.30;

import {RocketNodeStakingInterface} from "../../interface/node/RocketNodeStakingInterface.sol";
import {RocketStorageInterface} from "../../interface/RocketStorageInterface.sol";
import {RocketDAOProtocolSettingsNetworkInterface} from "../../interface/dao/protocol/settings/RocketDAOProtocolSettingsNetworkInterface.sol";
import {RocketMegapoolDelegateInterface} from "../../interface/megapool/RocketMegapoolDelegateInterface.sol";
import {RocketNetworkExitInterface} from "../../interface/network/RocketNetworkExitInterface.sol";
import {RocketNetworkParticipationInterface} from "../../interface/network/RocketNetworkParticipationInterface.sol";
import {BeaconStateVerifierInterface, VerifiedValidator, VerifiedParticipation} from "../../interface/util/BeaconStateVerifierInterface.sol";
import {RocketBase} from "../RocketBase.sol";
import {RocketMinipoolInterface} from "../../interface/minipool/RocketMinipoolInterface.sol";
import {RocketMinipoolManagerInterface} from "../../interface/minipool/RocketMinipoolManagerInterface.sol";
import {MinipoolStatus} from "../../types/MinipoolStatus.sol";
import {RocketMegapoolStorageLayout} from "../megapool/RocketMegapoolStorageLayout.sol";

/// @notice Implements the challenge and exit process for the protocol's performance requirements defined in RPIP-73
contract RocketNetworkParticipation is RocketBase, RocketNetworkParticipationInterface {
    // Events
    event MegapoolChallenged(address indexed megapoolAddress, uint32[] _validatorIds, uint256 indexed _challengeId, uint64 _startEpoch, bytes32 _root, uint256[] _participation);
    event MegapoolChallengeDefeated(uint256 _challengeId);
    event MegapoolChallengeFinalised(uint256 indexed challengeId, uint256 requestedCount, uint256 skippedCount);

    event MinipoolsChallenged(address indexed nodeAddress, uint256 indexed challengeId, address[] minipoolAddresses, uint64 startEpoch, bytes32 root, uint256[] participation);
    event MinipoolChallengeDefeated(uint256 challengeId);
    event MinipoolChallengeFinalised(uint256 indexed challengeId, uint256 requestedCount, uint256 skippedCount);

    event ChallengeBondLocked(uint256 indexed challengeId, address indexed proposer, uint256 amount, uint256 deadline);
    event ChallengeBondReleased(uint256 indexed challengeId, address indexed proposer, uint256 amount);
    event ChallengeBondSettled(uint256 indexed challengeId, address indexed proposer, address indexed responder, uint256 originalBond, uint256 recoveredAmount, uint256 reward, uint256 burn);

    // Internals
    uint64 constant internal slotsPerEpoch = 32;
    uint256 constant internal maxChallengeValidators = 32;
    uint256 constant internal slotRecencyThreshold = 1 hours;
    uint8 constant internal timelyTargetFlag = 1 << 1;

    modifier onlyLatestSelf() {
        require(address(this) == getContractAddress("rocketNetworkParticipation"), "Invalid or outdated contract");
        _;
    }

    // Construct
    constructor(RocketStorageInterface _rocketStorageAddress) RocketBase(_rocketStorageAddress) {
        version = 1;
    }

    /// @notice Returns the snapshotted bond terms and settlement state for either challenge type
    /// @param _challengeId ID of the challenge to query
    function getChallengeBondDetails(uint256 _challengeId) override public view returns (
        address proposer, address responder, uint256 bondAmount, uint256 responseDeadline, bool settled
    ) {
        _requireExistingChallenge(_challengeId);
        proposer = getAddress(keccak256(abi.encodePacked("participation.challenge.proposer", _challengeId)));
        responder = getAddress(keccak256(abi.encodePacked("participation.challenge.responder", _challengeId)));
        bondAmount = getUint(keccak256(abi.encodePacked("participation.challenge.bond", _challengeId)));
        responseDeadline = _getChallengeDeadline(_challengeId);
        settled = getBool(keccak256(abi.encodePacked("participation.challenge.bondSettled", _challengeId)));
    }

    /// @notice Returns the validator IDs in their submitted order
    /// @param _challengeId ID of the challenge to query
    function getChallengeValidatorIds(uint256 _challengeId) override public view returns (uint32[] memory) {
        _requireChallengeType(_challengeId, ChallengeType.Megapool);
        return abi.decode(getBytes(keccak256(abi.encodePacked("participation.challenge.validatorIds", _challengeId))), (uint32[]));
    }

    /// @notice Returns the minipool addresses belonging to a challenge
    /// @param _challengeId ID of the challenge to query
    function getChallengeMinipools(uint256 _challengeId) override public view returns (address[] memory) {
        _requireChallengeType(_challengeId, ChallengeType.Minipool);
        return abi.decode(getBytes(keccak256(abi.encodePacked("participation.challenge.minipools", _challengeId))), (address[]));
    }

    /// @notice Returns whether the challenge is against Minipools or a Megapool
    /// @param _challengeId ID of the challenge to query
    function getChallengeType(uint256 _challengeId) override public view returns (ChallengeType) {
        _requireExistingChallenge(_challengeId);
        return ChallengeType(getUint(keccak256(abi.encodePacked("participation.challenge.type", _challengeId))));
    }

    /// @notice Challenges 1 to 32 validator belonging to one Megapool sharing the same missed epochs
    /// @param _megapoolAddress Address of the Megapool with the challenged validators
    /// @param _validatorIds Unique internal IDs of 1 to 32 validators being challenged
    /// @param _startEpoch The first epoch of the range of epochs where participation dropped below the requirement
    /// @param _participation A bitmap of each epoch from _startEpoch encoding the epochs that the validator did not meet requirements
    /// @param _slotTimestamp Timestamp of the slot the slot proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function challengeMegapool(
        address _megapoolAddress,
        uint32[] calldata _validatorIds,
        uint64 _startEpoch,
        uint256[] calldata _participation,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) external onlyLatestSelf onlyRegisteredNode(msg.sender) onlyRegisteredMegapool(_megapoolAddress) {
        // Check global enable state
        require(_getPerformanceExitsEnabled(), "Performance exits disabled");
        // Check proof recency requirement
        require(_slotTimestamp + slotRecencyThreshold >= block.timestamp, "Slot proof too old");
        // Validate challenge
        _validateChallengeValidators(_megapoolAddress, _validatorIds);
        (uint256 period, bytes32 root) = _validateChallengeEpochs(_startEpoch, _participation, _slotTimestamp, _proofVersion, _proofData);
        _createMegapoolChallenge(_megapoolAddress, _validatorIds, _startEpoch, _participation, period, root);
    }

    function _createMegapoolChallenge(address _megapoolAddress, uint32[] calldata _validatorIds, uint64 _startEpoch, uint256[] calldata _participation, uint256 period, bytes32 root) internal {
        // Store challenge
        uint256 challengeId = _storeChallenge(ChallengeType.Megapool, _startEpoch, period, root);
        setAddress(keccak256(abi.encodePacked("participation.challenge.address", challengeId)), _megapoolAddress);
        // TODO: This is very inefficient storage, packing the IDs would save a lot of gas but require some custom encoding work
        setBytes(keccak256(abi.encodePacked("participation.challenge.validatorIds", challengeId)), abi.encode(_validatorIds));
        // Emit event
        emit MegapoolChallenged(_megapoolAddress, _validatorIds, challengeId, _startEpoch, root, _participation);
    }

    /// @notice Challenges 1 to 32 Minipools belonging to the same node operator sharing the same missed epochs
    /// @param _minipoolAddresses Array of Minipool addresses to challenge
    /// @param _startEpoch The first epoch of the range of epochs where participation dropped below the requirement
    /// @param _participation A bitmap of each epoch from _startEpoch encoding the epochs that the validator did not meet requirements
    /// @param _slotTimestamp Timestamp of the slot the slot proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function challengeMinipools(
        address[] calldata _minipoolAddresses,
        uint64 _startEpoch,
        uint256[] calldata _participation,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        // Check global enable state
        require(_getPerformanceExitsEnabled(), "Performance exits disabled");
        // Check proof recency requirement
        require(_slotTimestamp + slotRecencyThreshold >= block.timestamp, "Slot proof too old");
        // Validate challenge
        address nodeAddress = _validateChallengeMinipools(_minipoolAddresses);
        (uint256 period, bytes32 root) = _validateChallengeEpochs(_startEpoch, _participation, _slotTimestamp, _proofVersion, _proofData);
        _createMinipoolChallenge(nodeAddress, _minipoolAddresses, _startEpoch, _participation, period, root);
    }

    function _createMinipoolChallenge(address nodeAddress, address[] calldata _minipoolAddresses, uint64 _startEpoch, uint256[] calldata _participation, uint256 period, bytes32 root) internal {
        // Store challenge
        uint256 challengeId = _storeChallenge(ChallengeType.Minipool, _startEpoch, period, root);
        setAddress(keccak256(abi.encodePacked("participation.challenge.node", challengeId)), nodeAddress);
        setBytes(keccak256(abi.encodePacked("participation.challenge.minipools", challengeId)), abi.encode(_minipoolAddresses));
        // Emit event
        emit MinipoolsChallenged(nodeAddress, challengeId, _minipoolAddresses, _startEpoch, root, _participation);
    }

    /// @notice Allows a registered node other than the proposer to defeat the entire challenge by proving a listed validator activated after its start epoch
    /// @param _challengeId ID of the challenge
    /// @param _validatorId Internal ID of the listed validator the proof concerns
    /// @param _slotTimestamp Slot which the beacon state proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function respondWithMegapoolValidator(
        uint256 _challengeId,
        uint32 _validatorId,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        _requireAliveChallenge(_challengeId);
        bytes32 pubkeyHash = keccak256(_getChallengeValidatorPubkey(_challengeId, _validatorId));
        _respondWithValidator(_challengeId, pubkeyHash, _slotTimestamp, _proofVersion, _proofData);
    }

    /// @notice Defeats a minipool list using proof for one listed member
    /// @param _challengeId ID of the challenge
    /// @param _minipoolAddress Address of the Minipool the challenge was made against
    /// @param _slotTimestamp Slot which the beacon state proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function respondWithMinipoolValidator(
        uint256 _challengeId,
        address _minipoolAddress,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        _requireAliveChallenge(_challengeId);
        bytes32 pubkeyHash = keccak256(_getChallengeMinipoolPubkey(_challengeId, _minipoolAddress));
        _respondWithValidator(_challengeId, pubkeyHash, _slotTimestamp, _proofVersion, _proofData);
    }

    /// @notice Allows a registered node other than the proposer to defeat the entire challenge with a timely target vote by one listed validator
    /// @param _challengeId ID of the challenge
    /// @param _validatorId Internal ID of the listed validator the proof concerns
    /// @param _offset Offset from the start epoch to the epoch with fraud
    /// @param _challengeLeaf The leaf node containing the offset from the challenge merkle tree
    /// @param _challengeWitness Proof that the challenge leaf is contained in the challenge merkle tree
    /// @param _slotTimestamp Slot which the beacon state proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function respondWithMegapoolParticipation(
        uint256 _challengeId,
        uint32 _validatorId,
        uint64 _offset,
        uint256 _challengeLeaf,
        bytes32[] calldata _challengeWitness,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        _requireAliveChallenge(_challengeId);
        bytes32 pubkeyHash = keccak256(_getChallengeValidatorPubkey(_challengeId, _validatorId));
        _respondWithParticipation(_challengeId, pubkeyHash, _offset, _challengeLeaf, _challengeWitness, _slotTimestamp, _proofVersion, _proofData);
    }

    /// @notice Allows a registered node other than the proposer to defeat the entire challenge with a timely target vote by one listed validator
    /// @param _challengeId ID of the challenge
    /// @param _minipoolAddress Address of the Minipool the challenge was made against
    /// @param _offset Offset from the start epoch to the epoch with fraud
    /// @param _challengeLeaf The leaf node containing the offset from the challenge merkle tree
    /// @param _challengeWitness Proof that the challenge leaf is contained in the challenge merkle tree
    /// @param _slotTimestamp Slot which the beacon state proof was generated against
    /// @param _proofVersion Encoding version understood by the beacon verifier
    /// @param _proofData ABI-encoded proof bundle for the requested verification
    function respondWithMinipoolParticipation(
        uint256 _challengeId,
        address _minipoolAddress,
        uint64 _offset,
        uint256 _challengeLeaf,
        bytes32[] calldata _challengeWitness,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        _requireAliveChallenge(_challengeId);
        bytes32 pubkeyHash = keccak256(_getChallengeMinipoolPubkey(_challengeId, _minipoolAddress));
        _respondWithParticipation(_challengeId, pubkeyHash, _offset, _challengeLeaf, _challengeWitness, _slotTimestamp, _proofVersion, _proofData);
    }

    /// @notice Unlocks an undefeated challenge's bond after its response deadline, independently of exit finalisation
    /// @param _challengeId ID of the challenge to release the bond for
    function releaseChallengeBond(uint256 _challengeId) override external onlyLatestSelf {
        // Query bond details
        (address proposer,, uint256 bond, uint256 deadline, bool settled) = getChallengeBondDetails(_challengeId);
        // Validate state
        require(!getBool(keccak256(abi.encodePacked("participation.challenge.responded", _challengeId))), "Challenge was defeated");
        require(!settled, "Bond already settled");
        require(block.timestamp > deadline, "Challenge period has not passed");
        // Store bond settled flag
        setBool(keccak256(abi.encodePacked("participation.challenge.bondSettled", _challengeId)), true);
        // Unlock bond
        _getNodeStaking().unlockRPL(proposer, bond);
        // Emit event
        emit ChallengeBondReleased(_challengeId, proposer, bond);
    }

    /// @notice Claims a defeated challenge's recoverable bond as staked RPL
    /// @param _challengeId ID of the challenge to claim the reward for
    function claimChallengeReward(uint256 _challengeId) override external onlyLatestSelf onlyRegisteredNode(msg.sender) {
        // Query challenge bond details
        (address proposer, address responder, uint256 bond,, bool settled) = getChallengeBondDetails(_challengeId);
        // Validate state
        require(getBool(keccak256(abi.encodePacked("participation.challenge.responded", _challengeId))), "Challenge was not defeated");
        require(msg.sender == responder, "Invalid responder");
        require(!settled, "Bond already settled");
        RocketNodeStakingInterface staking = _getNodeStaking();
        // Best effort reward from bond
        uint256 recovered = staking.getNodeStakedRPL(proposer);
        if (recovered > bond) recovered = bond;
        // Compute the 20% bond burn amount and remaining reward
        uint256 burn = recovered / 5;
        uint256 reward = recovered - burn;
        // Settle and clear the complete recorded lock, including any amount consumed by slashing
        setBool(keccak256(abi.encodePacked("participation.challenge.bondSettled", _challengeId)), true);
        staking.unlockRPL(proposer, bond);
        if (burn != 0) staking.burnRPL(proposer, burn);
        if (reward != 0) staking.transferRPL(proposer, responder, reward);
        // Emit event
        emit ChallengeBondSettled(_challengeId, proposer, responder, bond, recovered, reward, burn);
    }

    /// @notice Requests exits for an undefeated list, skipping validators already handled
    /// @param _challengeId ID of the successful challenge
    function finaliseChallenge(uint256 _challengeId) override external onlyLatestSelf {
        // Validate input
        _requireUnresolvedChallenge(_challengeId);
        // Check correct time has passed
        require(_getChallengeDeadline(_challengeId) < block.timestamp, "Not enough time has passed");
        // Write finalised flag
        setBool(keccak256(abi.encodePacked("participation.challenge.finalised", _challengeId)), true);
        // Execute type-specific finalise function
        if (getChallengeType(_challengeId) == ChallengeType.Minipool) {
            _finaliseMinipoolChallenge(_challengeId);
        } else {
            _finaliseMegapoolChallenge(_challengeId);
        }
    }

    // Internals

    /// @dev Returns the deadline of a challenge
    function _getChallengeDeadline(uint256 _challengeId) internal view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("participation.challenge.deadline", _challengeId)));
    }

    /// @dev Convenience function to get rocketNodeStaking contract interface
    function _getNodeStaking() internal view returns (RocketNodeStakingInterface) {
        return RocketNodeStakingInterface(getContractAddress("rocketNodeStaking"));
    }

    function _respondWithValidator(
        uint256 _challengeId,
        bytes32 _pubkeyHash,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) internal {
        // Check proof recency requirement
        require(_slotTimestamp + slotRecencyThreshold >= block.timestamp, "Slot proof too old");
        // Get challenge details
        uint256 startEpoch = getUint(keccak256(abi.encodePacked("participation.challenge.start", _challengeId)));
        VerifiedValidator memory verified = BeaconStateVerifierInterface(getContractAddress("beaconStateVerifier")).verifyValidator(_slotTimestamp, _proofVersion, _proofData);
        require(verified.validator.activationEpoch > startEpoch, "Validator was staking during challenge period");
        require(keccak256(verified.validator.pubkey) == _pubkeyHash, "Incorrect validator");
        // Defeat the challenge
        _defeatChallenge(_challengeId);
    }

    function _respondWithParticipation(
        uint256 _challengeId,
        bytes32 _pubkeyHash,
        uint64 _offset,
        uint256 _challengeLeaf,
        bytes32[] calldata _challengeWitness,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) internal {
        VerifiedParticipation memory verified = BeaconStateVerifierInterface(getContractAddress("beaconStateVerifier")).verifyParticipation(_slotTimestamp, _proofVersion, _proofData);
        require(verified.validatorPubkeyHash == _pubkeyHash, "Incorrect validator");
        _validateParticipationResponse(_challengeId, _offset, _challengeLeaf, _challengeWitness, verified);
        _defeatChallenge(_challengeId);
    }

    function _validateParticipationResponse(uint256 _challengeId, uint64 _offset, uint256 _challengeLeaf, bytes32[] calldata _challengeWitness, VerifiedParticipation memory verified) internal view {
        // Get challenge data
        bytes32 root = getBytes32(keccak256(abi.encodePacked("participation.challenge.root", _challengeId)));
        uint256 startEpoch = getUint(keccak256(abi.encodePacked("participation.challenge.start", _challengeId)));
        uint256 period = getUint(keccak256(abi.encodePacked("participation.challenge.period", _challengeId)));
        // Response must be for an epoch within the challenge window
        require(_offset < period, "Epoch too high");
        // Participation flags must show that participation did actually occur at the challenged epoch
        require(_validateParticipationFlags(verified.participationFlags), "Invalid participation");
        // Response must be to an epoch that was actually marked as missed
        {
            uint256 participationBit = _offset % 256;
            uint256 participationMask = uint256(1) << participationBit;
            require((_challengeLeaf & participationMask) != 0, "Epoch not challenged");
        }
        // Prove the epoch referred to by this offset was actually challenged
        {
            uint256 leafIndex = _offset / 256;
            uint256 leafCount = (period + 255) / 256;
            uint256 merklePath = _nextPowerOfTwo(leafCount) + leafIndex;
            bytes32 restoredRoot = _restoreMerkleRoot(bytes32(_challengeLeaf), merklePath, _challengeWitness);
            require(restoredRoot == root, "Invalid challenge proof");
        }
        // Calculate the expected slot for the proof (must be the 1st slot of the epoch following the challenged epoch)
        uint256 challengedEpoch = startEpoch + _offset;
        uint256 proofEpoch = verified.participationSlot / slotsPerEpoch;
        require(proofEpoch == challengedEpoch + 1, "Invalid slot");
    }

    function _finaliseMegapoolChallenge(uint256 _challengeId) internal {
        // Get contracts
        address megapoolAddress = getAddress(keccak256(abi.encodePacked("participation.challenge.address", _challengeId)));
        RocketMegapoolDelegateInterface megapool = RocketMegapoolDelegateInterface(megapoolAddress);
        RocketNetworkExitInterface networkExit = RocketNetworkExitInterface(getContractAddress("rocketNetworkExit"));
        // Decode validator IDs from storage
        uint32[] memory validatorIds = getChallengeValidatorIds(_challengeId);
        // Iterate and attempt to begin cooperative exit
        uint256 requestedCount;
        for (uint256 i = 0; i < validatorIds.length; ++i) {
            uint32 validatorId = validatorIds[i];
            RocketMegapoolStorageLayout.ValidatorInfo memory validator = megapool.getValidatorInfo(validatorId);
            // Check if validator exited via other means during challenge window
            if (validator.exiting || validator.exited ||
            networkExit.getMegapoolExitType(megapoolAddress, validatorId) != RocketNetworkExitInterface.ExitType.None ||
                networkExit.getMegapoolCooperativeExitStart(megapoolAddress, validatorId) != 0) {
                continue;
            }
            // Request the exit
            networkExit.requestMegapoolExit(megapoolAddress, validatorId);
            ++requestedCount;
        }
        // Emit event
        emit MegapoolChallengeFinalised(_challengeId, requestedCount, validatorIds.length - requestedCount);
    }

    function _finaliseMinipoolChallenge(uint256 _challengeId) internal {
        address[] memory minipools = getChallengeMinipools(_challengeId);
        RocketNetworkExitInterface networkExit = RocketNetworkExitInterface(getContractAddress("rocketNetworkExit"));
        uint256 requestedCount;
        for (uint256 i = 0; i < minipools.length; ++i) {
            RocketMinipoolInterface minipool = RocketMinipoolInterface(minipools[i]);
            if (networkExit.getMinipoolCooperativeExitStart(minipools[i]) != 0 ||
            minipool.getFinalised() || minipool.getUserDistributed()) {
                continue;
            }
            // RocketNetworkExit retains responsibility for status validation, retry backoff and accounting
            networkExit.requestMinipoolExit(minipools[i]);
            ++requestedCount;
        }
        // Emit event
        emit MinipoolChallengeFinalised(_challengeId, requestedCount, minipools.length - requestedCount);
    }

    /// @dev Writes challenge data to storage and returns challenge ID
    function _storeChallenge(ChallengeType _type, uint64 _startEpoch, uint256 _period, bytes32 _root) internal returns (uint256 challengeId) {
        challengeId = getUint(keccak256("participation.challenge.count")) + 1;
        setUint(keccak256("participation.challenge.count"), challengeId);
        setUint(keccak256(abi.encodePacked("participation.challenge.type", challengeId)), uint256(_type));
        setBytes32(keccak256(abi.encodePacked("participation.challenge.root", challengeId)), _root);
        setUint(keccak256(abi.encodePacked("participation.challenge.time", challengeId)), block.timestamp);
        setUint(keccak256(abi.encodePacked("participation.challenge.start", challengeId)), _startEpoch);
        setUint(keccak256(abi.encodePacked("participation.challenge.period", challengeId)), _period);
        uint256 bond = _getNetworkSettings().getPerformanceChallengeBond();
        uint256 deadline = block.timestamp + _getParticipationChallengeTime();
        setAddress(keccak256(abi.encodePacked("participation.challenge.proposer", challengeId)), msg.sender);
        setUint(keccak256(abi.encodePacked("participation.challenge.bond", challengeId)), bond);
        setUint(keccak256(abi.encodePacked("participation.challenge.deadline", challengeId)), deadline);
        _getNodeStaking().lockRPL(msg.sender, bond);
        // Emit event
        emit ChallengeBondLocked(challengeId, msg.sender, bond, deadline);
    }

    function _validateChallengeMinipools(address[] calldata _minipools) internal view returns (address nodeAddress) {
        require(_minipools.length > 0, "No validators supplied");
        require(_minipools.length <= maxChallengeValidators, "Too many validators");
        RocketNetworkExitInterface networkExit = RocketNetworkExitInterface(getContractAddress("rocketNetworkExit"));
        for (uint256 i = 0; i < _minipools.length; ++i) {
            for (uint256 j = 0; j < i; ++j) {
                require(_minipools[j] != _minipools[i], "Duplicate validator");
            }
            require(getBool(keccak256(abi.encodePacked("minipool.exists", _minipools[i]))), "Invalid minipool");
            RocketMinipoolInterface minipool = RocketMinipoolInterface(_minipools[i]);
            if (i == 0) nodeAddress = minipool.getNodeAddress();
            else require(minipool.getNodeAddress() == nodeAddress, "Different node operators");
            require(minipool.getStatus() == MinipoolStatus.Staking, "Minipool is not staking");
            require(!minipool.getFinalised(), "Minipool is finalised");
            require(!minipool.getUserDistributed(), "User capital already distributed");
            require(networkExit.getMinipoolCooperativeExitStart(_minipools[i]) == 0, "Minipool already requested to exit");
        }
    }

    function _getChallengeMinipoolPubkey(uint256 _challengeId, address _minipoolAddress) internal view returns (bytes memory) {
        address[] memory minipools = getChallengeMinipools(_challengeId);
        for (uint256 i = 0; i < minipools.length; ++i) {
            if (minipools[i] == _minipoolAddress) {
                return RocketMinipoolManagerInterface(getContractAddress("rocketMinipoolManager")).getMinipoolPubkey(_minipoolAddress);
            }
        }
        revert("Validator not in challenge");
    }

    /// @dev Validate and hash the participation tree
    function _validateChallengeEpochs(
        uint64 _startEpoch,
        uint256[] calldata _participation,
        uint64 _slotTimestamp,
        uint256 _proofVersion,
        bytes calldata _proofData
    ) internal view returns (uint256 period, bytes32 root) {
        // Verify the slot proof
        BeaconStateVerifierInterface beaconStateVerifier = BeaconStateVerifierInterface(getContractAddress("beaconStateVerifier"));
        uint64 verifiedSlot = beaconStateVerifier.verifySlot(_slotTimestamp, _proofVersion, _proofData).slot;
        // Validate start epoch
        uint256 currentEpoch = verifiedSlot / slotsPerEpoch;
        require(_startEpoch < currentEpoch, "Challenge starts in future");
        period = _getPerformancePeriod();
        require(_startEpoch + period + _getProofBuffer() > currentEpoch, "Challenge too recent");
        uint256 elapsedEpochs = currentEpoch - _startEpoch;
        uint256 challengeableEpochs = elapsedEpochs < period ? elapsedEpochs : period;
        // Validate length and padding of bitmap
        require(_validateParticipationBitmap(period, challengeableEpochs, _participation), "Invalid participation bitmap");
        // Compute the hamming weight and confirm against performance requirement
        require(_calculateHammingWeight(_participation) >= _getMinimumPerformanceRequirement(period), "Participation is above requirement");
        // Compute and return the merkle tree root
        root = _hashTree(_participation);
    }

    /// @dev Validate every list member before storing the shared challenge
    function _validateChallengeValidators(address _megapoolAddress, uint32[] calldata _validatorIds) internal view {
        require(_validatorIds.length > 0, "No validators supplied");
        require(_validatorIds.length <= maxChallengeValidators, "Too many validators");
        RocketMegapoolDelegateInterface megapool = RocketMegapoolDelegateInterface(_megapoolAddress);
        RocketNetworkExitInterface networkExit = RocketNetworkExitInterface(getContractAddress("rocketNetworkExit"));
        for (uint256 i = 0; i < _validatorIds.length; ++i) {
            uint32 validatorId = _validatorIds[i];
            for (uint256 j = 0; j < i; ++j) {
                require(_validatorIds[j] != validatorId, "Duplicate validator");
            }
            RocketMegapoolStorageLayout.ValidatorInfo memory validator = megapool.getValidatorInfo(validatorId);
            require(validator.staked, "Validator not staked");
            require(!validator.dissolved, "Validator is dissolved");
            require(!validator.exiting, "Already exiting");
            require(!validator.exited, "Already exited");
            require(networkExit.getMegapoolCooperativeExitStart(_megapoolAddress, validatorId) == 0, "Exit has already been requested");
            require(networkExit.getMegapoolExitType(_megapoolAddress, validatorId) == RocketNetworkExitInterface.ExitType.None, "Validator exit already tracked");
        }
    }

    /// @dev Resolve a pubkey only when the supplied internal ID belongs to this challenge
    function _getChallengeValidatorPubkey(uint256 _challengeId, uint32 _validatorId) internal view returns (bytes memory) {
        uint32[] memory validatorIds = getChallengeValidatorIds(_challengeId);
        for (uint256 i = 0; i < validatorIds.length; ++i) {
            if (validatorIds[i] == _validatorId) {
                address megapoolAddress = getAddress(keccak256(abi.encodePacked("participation.challenge.address", _challengeId)));
                return RocketMegapoolDelegateInterface(megapoolAddress).getValidatorPubkey(_validatorId);
            }
        }
        revert("Validator not in challenge");
    }

    function _restoreMerkleRoot(bytes32 _leaf, uint256 _gindex, bytes32[] calldata _witnesses) internal view returns (bytes32) {
        // Removing exactly one path level per witness must leave only the root bit
        require(_gindex >> _witnesses.length == 1, "Invalid witness length");
        bytes32 value = _leaf;
        uint256 i = 0;
        while (_gindex != 1) {
            if (_gindex % 2 == 1) {
                value = _efficientSha256(_witnesses[i], value);
            } else {
                value = _efficientSha256(value, _witnesses[i]);
            }
            _gindex /= 2;
            unchecked {
                i++;
            }
        }
        return value;
    }

    /// @dev Validate length and padding of a given participation bitmap
    /// @param _period The challenge period in epochs
    /// @param _challengeableEpochs The number of epochs which are actually challengable (lower than current epoch)
    /// @param _participationBitmap The participation bitmap
    function _validateParticipationBitmap(
        uint256 _period,
        uint256 _challengeableEpochs,
        uint256[] calldata _participationBitmap
    ) internal pure returns (bool) {
        uint256 expectedLength = (_period + 255) / 256;
        if (_participationBitmap.length != expectedLength) return false;
        if (_challengeableEpochs > _period) return false;

        uint256 fullWords = _challengeableEpochs / 256;
        uint256 remainder = _challengeableEpochs % 256;

        if (remainder != 0) {
            uint256 validBitsMask = (uint256(1) << remainder) - 1;
            if ((_participationBitmap[fullWords] & ~validBitsMask) != 0) return false;
            fullWords++;
        }

        for (uint256 i = fullWords; i < _participationBitmap.length; ++i) {
            if (_participationBitmap[i] != 0) return false;
        }

        return true;
    }

    /// @dev Returns true if performance exits are globally enabled
    function _getPerformanceExitsEnabled() internal view returns (bool) {
        return _getNetworkSettings().getPerformanceExitsEnabled();
    }

    function _getParticipationChallengeTime() internal view returns (uint256) {
        return _getNetworkSettings().getPerformanceChallengePeriod();
    }

    /// @dev Gets the performance measurement period in epochs
    function _getPerformancePeriod() internal view returns (uint256) {
        return _getNetworkSettings().getPerformancePeriod();
    }

    /// @dev Returns the number of epochs that must be missed for a challenge to be valid
    function _getMinimumPerformanceRequirement(uint256 _period) internal view returns (uint256) {
        uint256 threshold = _getNetworkSettings().getPerformanceThreshold();
        uint256 missed = _period * (calcBase - threshold);
        return (missed + calcBase - 1) / calcBase;
    }

    /// @dev Returns the buffer time (in epochs) for proofs to limit the age of performance challenges
    function _getProofBuffer() internal view returns (uint256) {
        return _getNetworkSettings().getPerformanceProofBuffer();
    }

    function _getNetworkSettings() internal view returns (RocketDAOProtocolSettingsNetworkInterface) {
        return RocketDAOProtocolSettingsNetworkInterface(getContractAddress("rocketDAOProtocolSettingsNetwork"));
    }

    /// @dev Constructs a merkle tree from the given leaves and returns the root hash
    function _hashTree(uint256[] calldata _leaves) internal view returns (bytes32) {
        uint256 leafCount = _leaves.length;
        require(leafCount != 0, "Invalid tree");

        uint256 width = _nextPowerOfTwo(leafCount);
        bytes32[] memory tree = new bytes32[](width);

        for (uint256 i = 0; i < leafCount; ++i) {
            tree[i] = bytes32(_leaves[i]);
        }

        while (width > 1) {
            for (uint256 i = 0; i < width; i += 2) {
                tree[i / 2] = _efficientSha256(tree[i], tree[i + 1]);
            }
            width /= 2;
        }

        return tree[0];
    }

    /// @dev Returns the closest power of two value equal or greater than the given value
    function _nextPowerOfTwo(uint256 _value) internal pure returns (uint256) {
        require(_value != 0, "Invalid length");
        uint256 result = 1;
        while (result < _value) {
            require(result <= type(uint256).max / 2, "Length too large");
            result *= 2;
        }
        return result;
    }

    /// @dev Returns true if the given participation flags meet the requirement
    function _validateParticipationFlags(uint8 _participationFlags) internal pure returns (bool) {
        return _participationFlags & timelyTargetFlag != 0;
    }



    /// @dev Marks the given challenge as defeated
    function _defeatChallenge(uint256 _challengeId) internal {
        // Cancel the challenge
        setBool(keccak256(abi.encodePacked("participation.challenge.responded", _challengeId)), true);
        setAddress(keccak256(abi.encodePacked("participation.challenge.responder", _challengeId)), msg.sender);
        // Emit event
        if (getChallengeType(_challengeId) == ChallengeType.Minipool) emit MinipoolChallengeDefeated(_challengeId);
        else emit MegapoolChallengeDefeated(_challengeId);
    }

    /// @dev Reject challenges that do not match a specific type
    function _requireChallengeType(uint256 _challengeId, ChallengeType _type) internal view {
        require(getChallengeType(_challengeId) == _type, "Incorrect challenge type");
    }

    /// @dev Reject challenges that have reached either terminal state
    function _requireUnresolvedChallenge(uint256 _challengeId) internal view {
        _requireExistingChallenge(_challengeId);
        require(!getBool(keccak256(abi.encodePacked("participation.challenge.responded", _challengeId))), "Challenge was defeated");
        require(!getBool(keccak256(abi.encodePacked("participation.challenge.finalised", _challengeId))), "Challenge already finalised");
    }

    /// @dev Reverts if a challenge does not exists or has already expired
    function _requireAliveChallenge(uint256 _challengeId) internal view {
        _requireUnresolvedChallenge(_challengeId);
        require(_getChallengeDeadline(_challengeId) >= block.timestamp, "Challenge period has passed");
        require(msg.sender != getAddress(keccak256(abi.encodePacked("participation.challenge.proposer", _challengeId))), "Cannot defeat own challenge");
    }

    /// @dev Reverts if a challenge does not exists
    function _requireExistingChallenge(uint256 _challengeId) internal view {
        uint256 challengeTime = getUint(keccak256(abi.encodePacked("participation.challenge.time", _challengeId)));
        require(challengeTime != 0, "Invalid challenge");
    }

    /// @dev Computes the hamming weight of the given participation bitmap
    /// @param _participationBitmap The participation bitmap
    function _calculateHammingWeight(uint256[] calldata _participationBitmap) internal pure returns (uint256) {
        // TODO: We could return as soon as the requirement is met instead of calculating and returning the full result
        // Kernighan algorithm is optimised for sparse bitmap hamming weight calculation
        uint256 count = 0;
        unchecked {
            for (uint256 i = 0; i < _participationBitmap.length; ++i) {
                uint256 x = _participationBitmap[i];

                while (x != 0) {
                    x &= x - 1; // clear lowest set bit
                    ++count;
                }
            }
        }
        return count;
    }

    /// @dev Concatenates two bytes32 values and returns a SHA256 of the result
    function _efficientSha256(bytes32 _left, bytes32 _right) internal view returns (bytes32 ret) {
        assembly {
            mstore(0x00, _left)
            mstore(0x20, _right)

            let result := staticcall(gas(), 0x02, 0x00, 0x40, 0x00, 0x20)
            if iszero(result) {
                revert(0, 0)
            }

            ret := mload(0x00)
        }
    }
}

// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.30;

import {SafeCast} from "@openzeppelin4/contracts/utils/math/SafeCast.sol";
import {Math} from "@openzeppelin4/contracts/utils/math/Math.sol";

import {RocketDAONodeTrustedInterface} from "../../interface/dao/node/RocketDAONodeTrustedInterface.sol";
import {RocketDAOProtocolSettingsMinipoolInterface} from "../../interface/dao/protocol/settings/RocketDAOProtocolSettingsMinipoolInterface.sol";
import {RocketDAOProtocolSettingsNetworkInterface} from "../../interface/dao/protocol/settings/RocketDAOProtocolSettingsNetworkInterface.sol";
import {RocketMinipoolPenaltyInterface} from "../../interface/minipool/RocketMinipoolPenaltyInterface.sol";
import {RocketMinipoolInterface} from "../../interface/minipool/RocketMinipoolInterface.sol";
import {RocketNetworkPenaltiesInterface} from "../../interface/network/RocketNetworkPenaltiesInterface.sol";
import {RocketNetworkSnapshotsTimeInterface} from "../../interface/network/RocketNetworkSnapshotsTimeInterface.sol";
import {RocketStorageInterface} from "../../interface/RocketStorageInterface.sol";
import {RocketBase} from "../RocketBase.sol";

/// @notice Accounts for MEV theft and non-exit penalties on minipools
contract RocketNetworkPenalties is RocketBase, RocketNetworkPenaltiesInterface {
    // Constants
    uint256 constant internal penaltyMaximumPeriod = 7 days;
    bytes32 constant internal penaltyKey = keccak256(abi.encodePacked("minipool.running.penalty"));

    // Events
    event PenaltySubmitted(address indexed from, address indexed minipool, uint256 block, uint256 time);
    event PenaltyApplied(address indexed minipool, uint256 block, uint256 time);
    event PenaltyUpdated(address indexed minipool, uint256 penalty, uint256 time);

    // Construct
    constructor(RocketStorageInterface _rocketStorageAddress) RocketBase(_rocketStorageAddress) {
        version = 3;
    }

    /// @notice Adds a nominal ETH exit penalty to the minipool's combined penalty rate
    /// @param _minipool Address of the minipool to penalise
    /// @param _penaltyAmount Nominal penalty in wei; actual collection depends on the distributable node share and rate cap
    function applyExitPenalty(address _minipool, uint256 _penaltyAmount) override external onlyLatestContract("rocketNetworkExit", msg.sender) onlyRegisteredMinipool(_minipool) {
        _initialisePenaltyRates(_minipool);
        uint256 nodeDepositBalance = RocketMinipoolInterface(_minipool).getNodeDepositBalance();
        uint256 rateDelta = Math.mulDiv(_penaltyAmount, calcBase, nodeDepositBalance);
        addUint(keccak256(abi.encodePacked("network.penalties.rate.exit", _minipool)), rateDelta);
        _publishPenaltyRate(_minipool);
    }

    /// @notice Returns the number of votes in favour of the given penalty
    /// @param _minipool Address of the accused minipool
    /// @param _block Block that the theft occurred (used for uniqueness)
    function getVoteCount(address _minipool, uint256 _block) override external view returns (uint256) {
        bytes32 submissionCountKey = keccak256(abi.encodePacked("minipool.penalty.submission", _minipool, _block));
        return getUint(submissionCountKey);
    }

    /// @notice Votes to penalise a minipool for MEV theft (only callable by oDAO)
    /// @param _minipool Address of the accused minipool
    /// @param _block Block that the theft occurred (used for uniqueness)
    function submitPenalty(address _minipool, uint256 _block) override external onlyTrustedNode(msg.sender) onlyRegisteredMinipool(_minipool) {
        require(_block < block.number, "Invalid block number");
        // Get submission keys
        bytes32 nodeSubmissionKey = keccak256(abi.encodePacked("minipool.penalty.submission", msg.sender, _minipool, _block));
        bytes32 submissionCountKey = keccak256(abi.encodePacked("minipool.penalty.submission", _minipool, _block));
        // Check & update node submission status
        require(!getBool(nodeSubmissionKey), "Duplicate submission from node");
        setBool(nodeSubmissionKey, true);
        // Increment submission count
        uint256 submissionCount = getUint(submissionCountKey) + 1;
        setUint(submissionCountKey, submissionCount);
        // Maybe execute
        _maybeApplyPenalty(_minipool, _block, submissionCount);
        // Emit event
        emit PenaltySubmitted(msg.sender, _minipool, _block, block.timestamp);
    }

    /// @notice Manually execute a penalty that has hit majority vote
    /// @param _minipool Address of the accused minipool
    /// @param _block Block that the theft occurred (used for uniqueness)
    function executeUpdatePenalty(address _minipool, uint256 _block) override external {
        // Get submission count
        bytes32 submissionCountKey = keccak256(abi.encodePacked("minipool.penalty.submission", _minipool, _block));
        uint256 submissionCount = getUint(submissionCountKey);
        // Apply penalty if relevant conditions are met
        _maybeApplyPenalty(_minipool, _block, submissionCount);
    }

    /// @notice Returns the running total of penalties at a given timestamp
    /// @param _time The timestamp to compute running total for
    function getPenaltyRunningTotalAtTime(uint64 _time) override external view returns (uint256) {
        RocketNetworkSnapshotsTimeInterface rocketNetworkSnapshotsTime = RocketNetworkSnapshotsTimeInterface(getContractAddress("rocketNetworkSnapshotsTime"));
        return rocketNetworkSnapshotsTime.lookup(penaltyKey, _time);
    }

    /// @notice Returns the running total of penalties at the current time
    function getCurrentPenaltyRunningTotal() override external view returns (uint256) {
        RocketNetworkSnapshotsTimeInterface rocketNetworkSnapshotsTime = RocketNetworkSnapshotsTimeInterface(getContractAddress("rocketNetworkSnapshotsTime"));
        (,,uint192 value) =  rocketNetworkSnapshotsTime.latest(penaltyKey);
        return uint256(value);
    }

    /// @notice Returns the current maximum penalty based on the running total limitation
    function getCurrentMaxPenalty() override external view returns (uint256) {
        // Get contracts
        RocketNetworkSnapshotsTimeInterface rocketNetworkSnapshotsTime = RocketNetworkSnapshotsTimeInterface(getContractAddress("rocketNetworkSnapshotsTime"));
        RocketDAOProtocolSettingsMinipoolInterface rocketDAOProtocolSettingsMinipool = RocketDAOProtocolSettingsMinipoolInterface(getContractAddress("rocketDAOProtocolSettingsMinipool"));
        // Grab max weekly penalty
        uint256 maxPenalty = rocketDAOProtocolSettingsMinipool.getMaximumPenaltyCount();
        // Get running total from 7 days ago
        uint256 earlierTime = 0;
        if (block.timestamp > penaltyMaximumPeriod) {
            earlierTime = block.timestamp - penaltyMaximumPeriod;
        }
        uint256 earlierRunningTotal = uint256(rocketNetworkSnapshotsTime.lookup(penaltyKey, SafeCast.toUint64(earlierTime)));
        // Get current running total
        (,, uint192 currentRunningTotal) = rocketNetworkSnapshotsTime.latest(penaltyKey);
        // Cap the penalty at the maximum amount based on past 7 days
        uint256 currentTotal = uint256(currentRunningTotal) - earlierRunningTotal;
        if (currentTotal > maxPenalty) return 0;
        return maxPenalty - currentTotal;
    }

    /// @dev If a penalty has not been applied and hit majority, execute the penalty
    /// @param _minipool Address of the accused minipool
    /// @param _block Block that the theft occurred (used for uniqueness)
    function _maybeApplyPenalty(address _minipool, uint256 _block, uint256 _submissionCount) internal {
        // Check this penalty hasn't already reach majority and been applied
        bytes32 penaltyAppliedKey = keccak256(abi.encodePacked("minipool.penalty.submission.applied", _minipool, _block));
        require(!getBool(penaltyAppliedKey), "Penalty already applied");
        // Check for majority
        RocketDAONodeTrustedInterface rocketDAONodeTrusted = RocketDAONodeTrustedInterface(getContractAddress("rocketDAONodeTrusted"));
        RocketDAOProtocolSettingsNetworkInterface rocketDAOProtocolSettingsNetwork = RocketDAOProtocolSettingsNetworkInterface(getContractAddress("rocketDAOProtocolSettingsNetwork"));
        if (calcBase * _submissionCount / rocketDAONodeTrusted.getMemberCount() >= rocketDAOProtocolSettingsNetwork.getNodePenaltyThreshold()) {
            // Apply penalty and mark as applied
            setBool(penaltyAppliedKey, true);
            _applyPenalty(_minipool);
            // Emit event
            emit PenaltyApplied(_minipool, _block, block.timestamp);
        }
    }

    /// @dev Applies a penalty up to given amount, honouring the max penalty parameter
    function _applyPenalty(address _minipool) internal {
        // Get contracts
        RocketNetworkSnapshotsTimeInterface rocketNetworkSnapshotsTime = RocketNetworkSnapshotsTimeInterface(getContractAddress("rocketNetworkSnapshotsTime"));
        RocketDAOProtocolSettingsMinipoolInterface rocketDAOProtocolSettingsMinipool = RocketDAOProtocolSettingsMinipoolInterface(getContractAddress("rocketDAOProtocolSettingsMinipool"));
        // Grab max weekly penalty
        uint256 maxPenalty = rocketDAOProtocolSettingsMinipool.getMaximumPenaltyCount();
        // Get running total from 7 days ago
        uint256 earlierTime = 0;
        if (block.timestamp > penaltyMaximumPeriod) {
            earlierTime = block.timestamp - penaltyMaximumPeriod;
        }
        uint256 earlierRunningTotal = rocketNetworkSnapshotsTime.lookup(penaltyKey, SafeCast.toUint64(earlierTime));
        // Get current running total
        (,, uint192 currentRunningTotal) = rocketNetworkSnapshotsTime.latest(penaltyKey);
        // Prevent the running penalty total from exceeding the maximum amount
        uint256 currentTotal = uint256(currentRunningTotal) - earlierRunningTotal;
        require(currentTotal < maxPenalty, "Max penalty exceeded");
        uint256 currentMaxPenalty = maxPenalty - currentTotal;
        // Insert new running total
        rocketNetworkSnapshotsTime.push(penaltyKey, currentRunningTotal + 1);
        // Increment the penalty count on this minipool
        _incrementMinipoolPenaltyCount(_minipool);
    }

    /// @notice Returns the number of penalties for a given minipool
    /// @param _minipool Address of the minipool to query
    function getPenaltyCount(address _minipool) override external view returns (uint256) {
        return getUint(keccak256(abi.encodePacked("network.penalties.penalty", _minipool)));
    }

    /// @dev Increments the number of penalties against given minipool and updates penalty rate appropriately
    function _incrementMinipoolPenaltyCount(address _minipool) internal {
        // Get contracts
        RocketDAOProtocolSettingsNetworkInterface rocketDAOProtocolSettingsNetwork = RocketDAOProtocolSettingsNetworkInterface(getContractAddress("rocketDAOProtocolSettingsNetwork"));
        // Calculate penalty count key
        bytes32 key = keccak256(abi.encodePacked("network.penalties.penalty", _minipool));
        // Get the current penalty count
        uint256 newPenaltyCount = getUint(key) + 1;
        // Update the penalty count
        setUint(key, newPenaltyCount);
        // First two penalties do not increase penalty rate
        if (newPenaltyCount < 3) {
            return;
        }
        newPenaltyCount = newPenaltyCount - 2;
        // Calculate the new penalty rate
        uint256 penaltyRate = newPenaltyCount * rocketDAOProtocolSettingsNetwork.getPerPenaltyRate();
        // Reprice only the oDAO contribution, preserving accumulated non-exit penalties
        _initialisePenaltyRates(_minipool);
        setUint(keccak256(abi.encodePacked("network.penalties.rate.odao", _minipool)), penaltyRate);
        _publishPenaltyRate(_minipool);
    }

    /// @dev Existing pre-v1.5 rates are legacy contributions. Read raw storage so a temporary cap cannot discard them
    function _initialisePenaltyRates(address _minipool) internal {
        bytes32 initialisedKey = keccak256(abi.encodePacked("network.penalties.rate.initialised", _minipool));
        if (getBool(initialisedKey)) return;
        setUint(keccak256(abi.encodePacked("network.penalties.rate.odao", _minipool)), getUint(keccak256(abi.encodePacked("minipool.penalty.rate", _minipool))));
        setUint(keccak256(abi.encodePacked("network.penalties.rate.exit", _minipool)), 0);
        setBool(initialisedKey, true);
    }

    /// @dev Publish the uncapped sum; the immutable minipool penalty contract applies the effective maximum when read
    function _publishPenaltyRate(address _minipool) internal {
        uint256 penaltyRate = getUint(keccak256(abi.encodePacked("network.penalties.rate.odao", _minipool)))
            + getUint(keccak256(abi.encodePacked("network.penalties.rate.exit", _minipool)));
        RocketMinipoolPenaltyInterface(getContractAddress("rocketMinipoolPenalty")).setPenaltyRate(_minipool, penaltyRate);
        emit PenaltyUpdated(_minipool, penaltyRate, block.timestamp);
    }

}

